 m.player({id:1,faction:'US',name:'Trainee',team:1,controller:'human',credits:cr(8000)}).player({id:2,faction:'IR',name:'Training Opposition',team:2,controller:n===5?'ai':'script',ai:n===5?'easy':'',credits:cr(2500)}).player({id:3,faction:'US',name:'Training Stores',team:1,controller:'script',credits:0}).player({id:4,faction:'SY',name:'Exercise Detachment',team:2,controller:'script',credits:cr(3000)});
