  fail(m,'service-aircraft-lost','Lose the marked strike aircraft before completing service.',all(tagDestroyed('training-aircraft'),eventCount('aircraft_serviced',{owner:1,tag:'training-aircraft',count:0,compare:'at_most'})));fail(m,'missile-exercise-lost','Destroy the missile source before intercepting its missile.',all(tagDestroyed('missile-target'),eventCount('missile_intercepted',{owner:4,count:0,compare:'at_most'})));fail(m,'evade-team-lost','Lose the marked infantry group before its movement exercise.',tagDestroyed('starting-rifles'));
  obj(m,'service','Complete service on the marked strike aircraft.',eventCount('aircraft_serviced',{tag:'training-aircraft',owner:1,count:1}));obj(m,'air-defense','Destroy the hostile aircraft.',tagDestroyed('hostile-aircraft'));obj(m,'missile-defense','Intercept one tactical missile.',eventCount('missile_intercepted',{owner:4,count:1}));obj(m,'evade','Move the marked rifle group to the danger marker, then return after the warning.',all(timer(sec(30)),objectiveDone('enter-mark'),tagInRegion('starting-rifles','base')));obj(m,'enter-mark','Move the marked rifle group to the exercise warning marker.',tagInRegion('starting-rifles','site1'));opt(m,'wing-safe','Keep both original aircraft alive.',all(tagAlive('training-aircraft'),tagAlive('training-fighter')));cp(m,'service-cycle',objectiveDone('service'),'Aircraft service is complete. Observe the distinct missile and air-defense counters.');
