  m.trigger({id:'first-convoy-ready',condition:timer(sec(20)),actions:[startConvoy('convoy-1'),warn('Convoy one is ready. Approve Advance, or Hold while an escort clears the chosen branch.')],speaker:'Convoy control'});
  m.trigger({id:'second-convoy-ready',condition:convoyDone('convoy-1'),actions:[checkpoint('first-arrival'),spawn('convoy-two','US.hauler',3,p(17,117),2),spawn('western-forward-repair','depot',1,p(53,78)),spawn('eastern-forward-repair','depot',2,p(64,78)),startConvoy('convoy-2'),warn('First delivery complete. Two separately owned forward repair depots are now available. Convoy two is ready.')],speaker:'Convoy control'});
